import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BHcoJYMQ.js";const m=JSON.parse('{"title":"Research method","description":"","frontmatter":{},"headers":[],"relativePath":"research/method.md","filePath":"research/method.md","lastUpdated":1794242772000}'),o={name:"research/method.md"};function n(s,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="research-method" tabindex="-1">Research method <a class="header-anchor" href="#research-method" aria-label="Permalink to &quot;Research method&quot;">​</a></h1><h2 id="collection-workflow" tabindex="-1">Collection workflow <a class="header-anchor" href="#collection-workflow" aria-label="Permalink to &quot;Collection workflow&quot;">​</a></h2><ol><li>Discover a candidate and record the official website.</li><li>Check its current assortment and qualify its competitor group.</li><li>Select an in-stock or explicitly unavailable plain white T-shirt SKU.</li><li>Copy the <a href="/white-tee-research/competitors/template.html">profile template</a> to a new Markdown file.</li><li>Collect product, price, policy, positioning, and customer evidence.</li><li>Add source IDs to the <a href="/white-tee-research/research/sources.html">source log</a>, then cite them beside claims.</li><li>Update the <a href="/white-tee-research/competitors/">directory</a> and <a href="/white-tee-research/research/comparison.html">comparison matrix</a>.</li><li>Review gaps and propose hypotheses separately from observed facts.</li></ol><h2 id="evidence-rules" tabindex="-1">Evidence rules <a class="header-anchor" href="#evidence-rules" aria-label="Permalink to &quot;Evidence rules&quot;">​</a></h2><ul><li>Prefer official product and policy pages for specifications, prices, assortment, and terms.</li><li>A brand claim is not an independently verified performance result. Label it as a claim.</li><li>Use independent reviews for customer signals; record sample size, selection method, dates, and incentives when known.</li><li>Every factual finding needs a source URL, access date, and relevant region or variant.</li><li>Mark unknowns <strong>Not researched</strong>, <strong>Not disclosed</strong>, or <strong>Not applicable</strong>. Never use zero to mean missing.</li><li>Preserve conflicting evidence and explain the disagreement.</li><li>Refresh changing facts before using them to make a decision.</li></ul><h2 id="price-normalization" tabindex="-1">Price normalization <a class="header-anchor" href="#price-normalization" aria-label="Permalink to &quot;Price normalization&quot;">​</a></h2><p>Record currency, region, tax treatment, regular price, observed sale price, pack quantity, and shipping separately. Calculate per-shirt price as pack price divided by shirt count. Do not compare unlike currencies without recording the exchange rate, source, and conversion date. Do not treat a temporary discount as regular pricing.</p><h2 id="status-and-confidence" tabindex="-1">Status and confidence <a class="header-anchor" href="#status-and-confidence" aria-label="Permalink to &quot;Status and confidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Candidate</td><td>Discovered; relevance not checked</td></tr><tr><td>Qualified</td><td>Current assortment and relevant product checked</td></tr><tr><td>In research</td><td>Profile partially populated</td></tr><tr><td>Reviewed</td><td>Core fields sourced and gaps explicitly documented</td></tr><tr><td>Refresh needed</td><td>Evidence is stale or contradictory</td></tr></tbody></table><p>Confidence applies to each claim: <strong>high</strong> for clear, directly supported facts; <strong>medium</strong> for partial or indirect support; <strong>low</strong> for tentative interpretations. Confidence is not a brand quality score.</p>',10)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
